def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def_count = sum(1 for a in opp if a == 'D')
    my_def_count = sum(1 for a in my if a == 'D')

    # Detect AllD: last 5 opponent moves all D
    if n >= 5:
        last5 = opp[-5:]
        if all(a == 'D' for a in last5):
            return 'D'

    # Exploit non-retaliatory cooperative opponents
    if opp_def_count == 0:
        if n < 2:
            return 'C'
        else:
            return 'D'

    # Check if opponent doesn't retaliate to our defections
    retaliation_count = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i+1] == 'D':
            retaliation_count += 1
    if my_def_count >= 2 and retaliation_count == 0:
        return 'D'

    # TFT with forgiveness
    my_last, opp_last = history[-1]
    if opp_last == 'C':
        return 'C'
    else:
        if my_last == 'C':
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            else:
                return 'C'
        else:
            return 'C'
